param([Parameter(Mandatory=$true)][ValidateSet('owner','observe')][string]$Mode,[Parameter(Mandatory=$true)][string]$FixtureRoot)
# ONLY the fixed finite Node fixture. Actual production C# is extracted, never
# the product helper loop. No force/kill/job-limit/parent-attribute APIs called.
$ErrorActionPreference='Stop'
$root=[IO.Path]::GetFullPath($FixtureRoot);$allowed=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../.codex-runtime/core-launch-lifetime'))
if([IO.Path]::GetDirectoryName($root) -ine $allowed -or [IO.Path]::GetFileName($root) -cnotmatch '^[a-f0-9-]{36}$'){throw 'harmless_fixture_containment'}
function SafePath([string]$file,[bool]$directory=$false){for($part=$file;$part;$part=[IO.Path]::GetDirectoryName($part)){if(Test-Path -LiteralPath $part){$item=Get-Item -LiteralPath $part -Force;if(($item.Attributes -band [IO.FileAttributes]::ReparsePoint)-ne 0){throw 'harmless_fixture_alias'}}};$item=Get-Item -LiteralPath $file -Force;if($directory -ne [bool]$item.PSIsContainer){throw 'harmless_fixture_kind'}}
function Digest([string]$file){SafePath $file;return (Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash.ToLowerInvariant()}
function TextDigest([string]$text){return [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($text))).ToLowerInvariant()}
function WriteNew([string]$name,$value){$bytes=[Text.Encoding]::UTF8.GetBytes(($value|ConvertTo-Json -Depth 30 -Compress)+"`n");$s=[IO.FileStream]::new((Join-Path $root $name),[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$s.Write($bytes,0,$bytes.Length);$s.Flush($true)}finally{$s.Dispose()}}
function Read([string]$name){$file=Join-Path $root $name;SafePath $file;return [IO.File]::ReadAllText($file)|ConvertFrom-Json -DateKind String}
SafePath $root $true;$case=Read 'case.json';$node=[IO.Path]::GetFullPath('C:/Users/Ant/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/bin/node.exe');$scriptFile=Join-Path $root 'fixture.js';$helper=Join-Path $PSScriptRoot 'owned-runtime-daemon-helper.ps1'
if($case.schema -cne 'ae-agent.harmless-launch-lifetime.v1' -or $case.nonce -cne [IO.Path]::GetFileName($root) -or $case.fixtureRoot -ine $root -or [IO.Path]::GetFullPath($case.node) -ine $node -or $case.nodeSha256 -cne '3602f2bb1a10f2cbab4c36886218a33c1ab3db87290e73b033c46c77147d0237' -or $case.ttlMs -ne 90000 -or $case.exitCode -ne 27 -or $case.fallbackAllowed -cne $false -or $case.coreTouched -cne $false -or $case.aeTouched -cne $false -or $case.ownerAckDeadlineMs -ne 45000 -or $case.observerDeadlineMs -ne 110000 -or $case.survivalIntervalMs -ne 5000 -or $case.jobMembershipIsDiagnostic -cne $true -or [DateTimeOffset]::UtcNow -ge [DateTimeOffset]::Parse($case.expiresAt) -or (Digest $scriptFile) -cne $case.scriptSha256 -or (Digest $helper) -cne $case.helperSha256 -or (Digest $PSCommandPath) -cne $case.harnessSha256 -or (Digest $node) -cne $case.nodeSha256){throw 'harmless_fixture_pin_invalid'}
$errors=$null;$tokens=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($helper,[ref]$tokens,[ref]$errors);if($errors.Count){throw 'harmless_production_parse_invalid'}
$add=$ast.Find({param($n)$n -is [Management.Automation.Language.CommandAst] -and $n.GetCommandName() -ceq 'Add-Type'},$true);$definition=$add.CommandElements|Where-Object {$_ -is [Management.Automation.Language.StringConstantExpressionAst]}|Select-Object -Last 1
if((TextDigest $definition.Value) -cne $case.productionCsharpSha256 -or !$definition.Value.Contains('0x01000000') -or !$definition.Value.Contains('IsInAnyJob')){throw 'harmless_production_definition_changed'}
Add-Type -TypeDefinition $definition.Value
function Identity([IntPtr]$handle){$v=[OwnedDaemonKernel]::Identity($handle)|ConvertTo-Json -Compress|ConvertFrom-Json -DateKind String;$v|Add-Member executableSha256 (Digest $node);if($v.imagePath -ine $node -or $v.executableSha256 -cne $case.nodeSha256){throw 'harmless_identity_invalid'};return $v}
function AssertIdentity([IntPtr]$handle,$expected){$v=Identity $handle;foreach($name in @('pid','birthFileTime','birthUtc','imagePath','executableSha256')){if([string]$v.$name -cne [string]$expected.$name){throw 'harmless_identity_changed'}};return $v}
function Argv($identity){$row=Get-CimInstance Win32_Process -Filter ('ProcessId='+[string]$identity.pid);if(!$row -or $row.ExecutablePath -ine $node){throw 'harmless_owned_argv_unavailable'};$argv=[OwnedDaemonKernel]::Args($row.CommandLine);if($argv.Count -ne 2 -or $argv[0] -ine $node -or $argv[1] -ine $scriptFile){throw 'harmless_owned_argv_invalid'};return @{argv=$argv;parentPid=$row.ParentProcessId}}
$handle=[IntPtr]::Zero
try{
 if($Mode -ceq 'owner'){
  if(Test-Path -LiteralPath (Join-Path $root 'launch-attempt.json')){throw 'harmless_launch_once_consumed'}
  WriteNew 'launch-attempt.json' @{nonce=$case.nonce;ownerPid=$PID;attemptedAt=[DateTimeOffset]::UtcNow.ToString('o');maximumCreates=1;fallbackAllowed=$false}
  $environment=[Collections.Generic.Dictionary[string,string]]::new([StringComparer]::OrdinalIgnoreCase);$environment['SystemRoot']='C:\Windows';$environment['WINDIR']='C:\Windows';$environment['PATH']=[IO.Path]::GetDirectoryName($node)
  # The returned actual handle is retained BEFORE identity/job/candidate checks.
  $handle=[OwnedDaemonKernel]::StartIndependent($node,$scriptFile,$root,$environment)
  $openedAt=[DateTimeOffset]::UtcNow.ToString('o');$inJob=[OwnedDaemonKernel]::IsInAnyJob($handle);$identity=Identity $handle;$argv=Argv $identity
  WriteNew 'job-membership-diagnostic.json' @{nonce=$case.nonce;identity=$identity;inAnyJob=$inJob;jobMembershipIsDiagnostic=$true;fallbackAllowed=$false}
  $candidate=@{schema=$case.schema;nonce=$case.nonce;identity=$identity;argv=$argv.argv;actualParentPid=$argv.parentPid;ownerPid=$PID;handleOpenedAt=$openedAt;inAnyJob=$inJob;helperSha256=$case.helperSha256;productionCsharpSha256=$case.productionCsharpSha256;scriptSha256=$case.scriptSha256;createdAt=[DateTimeOffset]::UtcNow.ToString('o');maximumCreates=1;fallbackAllowed=$false}
  if($candidate.actualParentPid -ne $PID){throw 'harmless_actual_parent_mismatch'};WriteNew 'candidate.json' $candidate
  @{ok=$true;phase='owner_actual_handle_held';fixtureRoot=$root;candidate=$candidate}|ConvertTo-Json -Depth 12 -Compress;[Console]::Out.Flush()
  $deadline=[DateTimeOffset]::UtcNow.AddMilliseconds(45000);$ack=$null
  while([DateTimeOffset]::UtcNow -lt $deadline){if(Test-Path -LiteralPath (Join-Path $root 'observer-captured.json')){$ack=Read 'observer-captured.json';break};if(([OwnedDaemonKernel]::Wait($handle,0)).signaled){throw 'harmless_child_exited_before_observer'};[Threading.Thread]::Sleep(250)}
  if(!$ack -or $ack.nonce -cne $case.nonce -or $ack.candidateRawSha256 -cne (Digest (Join-Path $root 'candidate.json')) -or $ack.inAnyJob -isnot [bool]){throw 'harmless_observer_ack_missing_or_invalid'}
  [void](AssertIdentity $handle $identity);if(([OwnedDaemonKernel]::Wait($handle,0)).signaled){throw 'harmless_not_alive_at_owner_release'}
  WriteNew 'owner-closing.json' @{nonce=$case.nonce;ownerPid=$PID;at=[DateTimeOffset]::UtcNow.ToString('o');observerPid=$ack.observerPid;childAliveOnSameHandle=$true;claim='owner_about_to_close_only_not_tool_completion'}
  @{ok=$true;phase='owner_complete';ownerPid=$PID;nonce=$case.nonce;childIdentity=$identity;exitCode=0;toolCompletionStillMustBeObservedExternally=$true}|ConvertTo-Json -Depth 12 -Compress;exit 0
 }
 $candidate=Read 'candidate.json';if($candidate.nonce -cne $case.nonce -or $candidate.inAnyJob -isnot [bool] -or $candidate.scriptSha256 -cne $case.scriptSha256 -or $candidate.helperSha256 -cne $case.helperSha256 -or $candidate.identity.imagePath -ine $node -or $candidate.identity.executableSha256 -cne $case.nodeSha256 -or $candidate.actualParentPid -ne $candidate.ownerPid){throw 'harmless_observer_candidate_invalid'}
 $handle=[OwnedDaemonKernel]::Open([int]$candidate.identity.pid,$false);$observerOpenedAt=[DateTimeOffset]::UtcNow.ToString('o');[void](AssertIdentity $handle $candidate.identity);[void](Argv $candidate.identity);$inJob=[OwnedDaemonKernel]::IsInAnyJob($handle)
 WriteNew 'observer-captured.json' @{nonce=$case.nonce;observerPid=$PID;capturedAt=$observerOpenedAt;candidateRawSha256=(Digest (Join-Path $root 'candidate.json'));identity=$candidate.identity;inAnyJob=$inJob}
 @{ok=$true;phase='observer_exact_handle_captured';observerPid=$PID;identity=$candidate.identity;inAnyJob=$inJob}|ConvertTo-Json -Depth 10 -Compress;[Console]::Out.Flush()
 $deadline=[DateTimeOffset]::UtcNow.AddMilliseconds(110000);$survived=$false;$terminal=$null
 while([DateTimeOffset]::UtcNow -lt $deadline){
  $wait=[OwnedDaemonKernel]::Wait($handle,0)
  if(!$survived -and (Test-Path -LiteralPath (Join-Path $root 'owner-tool-completed.json'))){$closed=Read 'owner-tool-completed.json';if($closed.nonce -cne $case.nonce -or $closed.ownerPid -ne $candidate.ownerPid -or $closed.exitCode -ne 0 -or $closed.evidenceSource -cne 'actual_owner_exec_tool_completion'){throw 'harmless_owner_tool_completion_invalid'};[void](AssertIdentity $handle $candidate.identity);$wait=[OwnedDaemonKernel]::Wait($handle,0);if($wait.waitResult -cne 'WAIT_TIMEOUT' -or $wait.signaled -cne $false -or $null -ne $wait.exitCode){throw 'harmless_did_not_survive_owner_tool_completion'};$survival=[Diagnostics.Stopwatch]::StartNew();while($survival.ElapsedMilliseconds -lt 5000){[Threading.Thread]::Sleep(250);[void](AssertIdentity $handle $candidate.identity);$wait=[OwnedDaemonKernel]::Wait($handle,0);if($wait.waitResult -cne 'WAIT_TIMEOUT' -or $wait.signaled -cne $false -or $null -ne $wait.exitCode){throw 'harmless_survival_interval_failed'}};$survival.Stop();$survived=$true;WriteNew 'survived-owner-tool.json' @{nonce=$case.nonce;observedAt=[DateTimeOffset]::UtcNow.ToString('o');wait=$wait;identity=$candidate.identity;ownerToolEvidence=$closed;survivalIntervalMs=$survival.ElapsedMilliseconds;creatorInAnyJob=$candidate.inAnyJob;observerInAnyJob=$inJob};@{ok=$true;phase='survived_actual_owner_tool_completion';wait=$wait}|ConvertTo-Json -Depth 8 -Compress;[Console]::Out.Flush()}
  if($wait.signaled){$terminal=$wait;break};[Threading.Thread]::Sleep(250)
 }
 if(!$terminal -or $terminal.waitResult -cne 'WAIT_OBJECT_0' -or $terminal.exitCode -ne 27 -or !$survived){throw 'harmless_lifetime_proof_incomplete'}
 $intent=Read 'self-exit-intent.json';if($intent.nonce -cne $case.nonce -or $intent.pid -ne $candidate.identity.pid -or $intent.reason -cne 'finite_test_owned_ttl' -or $intent.exitCode -ne 27){throw 'harmless_self_exit_intent_invalid'}
 WriteNew 'lifetime-result.json' @{schema='ae-agent.harmless-launch-lifetime-result.v1';nonce=$case.nonce;identity=$candidate.identity;observerPid=$PID;observerHandleOpenedAt=$observerOpenedAt;observedAt=[DateTimeOffset]::UtcNow.ToString('o');creatorInAnyJob=$candidate.inAnyJob;observerInAnyJob=$inJob;jobMembershipIsDiagnostic=$true;survivalIntervalMs=$survival.ElapsedMilliseconds;survivedOwnerToolCompletion=$true;wait=$terminal;fixtureOnly=$true;oldCoreCauseProven=$false;productionAcceptance=$false;fallbackUsed=$false}
 @{ok=$true;phase='harmless_lifetime_pass';wait=$terminal;fixtureOnly=$true;productionAcceptance=$false}|ConvertTo-Json -Depth 8 -Compress
}catch{
 $reason=$_.Exception;while($reason.InnerException){$reason=$reason.InnerException};$win32=if($reason -is [ComponentModel.Win32Exception]){$reason.NativeErrorCode}else{$null}
 if(!(Test-Path -LiteralPath (Join-Path $root ($Mode+'-failure.json')))){WriteNew ($Mode+'-failure.json') @{nonce=$case.nonce;mode=$Mode;reason=$reason.Message;win32Error=$win32;handleReturned=($handle -ne [IntPtr]::Zero);fallbackAllowed=$false;exitProven=$false;productionBlocked=$true}}
 @{ok=$false;phase='harmless_fixture_failed';code=$reason.Message;win32Error=$win32;fallbackAllowed=$false;productionBlocked=$true}|ConvertTo-Json -Compress;exit 32
}finally{if($handle -ne [IntPtr]::Zero){[OwnedDaemonKernel]::Dispose($handle)}}
